+            rotations[frameIndex] = userTransform.getRotation();
+            scales[frameIndex] = userTransform.getScale();
+        }
+
+        BoneTrack result = new BoneTrack(targetBoneIndex, times, translations,
+                rotations, scales);
+
+        return result;
+    }
